64743713233133443322322233\n3435364346335235433434536431464642533325336432334433324343343348345334335513343353573432462435433445\n1322332232123333231122235282322332132233243232231243253522221182232623322312232223332213122212222333\n1332242223122322223432422223223222231321422232323322315323254332421213323312211322342222121233222222\n2122222222222321221222211222242314232222112262321222232226222422222212222222222222222221222242222212";
    
    private const string ExampleInput = "987654321111111\n811111111111119\n234234234234278\n818181911112111";

    private long m_result = 0;
    
    public long GetResult(int amountOfBatteries)
    {
        string[] banks = MyInput.Split('\n');

        foreach (string bank in banks)
        {
            //Assume a bank has count >= amountOfBatteries
            
            int[] batteries = new int[amountOfBatteries];
            
            for (int i = 0; i < bank.Length; i++)
            {
                int joltage = int.Parse(bank[i].ToString());
                int elementsToGo = bank.Length - i;
                int calculateFromIndex = Math.Max(0, amountOfBatteries - elementsToGo);
                RecalculateBatteries(joltage, calculateFromIndex, ref batteries);
            }
            
            m_result += long.Parse(string.Concat(batteries));
        }

        return m_result;
    }

    private void RecalculateBatteries(int currentJoltage, int startingIndex, ref int[] batteries)
    {

        for (int i = startingIndex; i < batteries.Length; i++)
        {
            if (currentJoltage > batteries[i])
            {
                batteries[i] = currentJoltage;
                
                if (i + 1 >= batteries.Length) return;
                
                Array.Fill(batteries, 0, i+1, batteries.Length - i - 1);
                return;
            }
        }
    }
}